    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, SheetRepository sheetStore, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The role of a user name on the sheet: the one assigned, else clerk. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** Assign a role (clerk or steward) to a user name, replacing the one it had. The sheet is locked
     *  first, so two assignments to one name are made one at a time. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Role row = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        row.setRole(role);
        Role saved = roles.saveAndFlush(row);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk
 *  settling an OPEN claim above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects
 *  (OPEN again). */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code next} by a status change; approving or rejecting a
     *  PENDING claim is not a status change. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT, PENDING -> false;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due: OPEN, PENDING and SETTLED ones do. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is still open: OPEN or PENDING, so it goes overdue and gains the late charge. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}

